-- WNI PHASE 3 — ECONOMY
-- Applied to production: banking, credit, personal finance, marketplace,
-- supply-chain primitives and city-economy snapshots.
-- All exposed game tables are RLS-protected and economy mutations are service_role-only.

create table if not exists public.game_bank_accounts(id bigint generated by default as identity primary key,character_id bigint not null references public.game_characters(id) on delete cascade,account_number text not null unique,account_type text not null default 'savings',balance bigint not null default 0 check(balance>=0),status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.game_bank_transfers(id bigint generated by default as identity primary key,from_account_id bigint references public.game_bank_accounts(id),to_account_id bigint references public.game_bank_accounts(id),amount bigint not null check(amount>0),transfer_type text not null default 'transfer',reference_key text,created_at timestamptz not null default now());
create table if not exists public.game_bank_loans(id bigint generated by default as identity primary key,character_id bigint not null references public.game_characters(id) on delete cascade,account_id bigint references public.game_bank_accounts(id),principal bigint not null,outstanding_principal bigint not null,annual_interest_rate numeric(8,4) not null,term_months integer not null,installment bigint not null,status text not null default 'active',credit_score integer not null default 600,next_due_at timestamptz,created_at timestamptz not null default now(),closed_at timestamptz);
create table if not exists public.game_credit_history(id bigint generated by default as identity primary key,character_id bigint not null references public.game_characters(id) on delete cascade,loan_id bigint references public.game_bank_loans(id) on delete set null,event_type text not null,amount bigint not null default 0,score_delta integer not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.game_personal_finance_snapshots(id bigint generated by default as identity primary key,character_id bigint not null references public.game_characters(id) on delete cascade,period_key text not null,income bigint not null default 0,expenses bigint not null default 0,assets bigint not null default 0,liabilities bigint not null default 0,net_worth bigint not null default 0,created_at timestamptz not null default now(),unique(character_id,period_key));
create table if not exists public.game_supply_chain(id bigint generated by default as identity primary key,supplier_business_id bigint references public.game_businesses(id) on delete cascade,buyer_business_id bigint references public.game_businesses(id) on delete cascade,item_key text not null,quantity bigint not null,unit_price bigint not null,status text not null default 'pending',created_at timestamptz not null default now(),fulfilled_at timestamptz);
create table if not exists public.game_city_economy_snapshots(id bigint generated by default as identity primary key,city_id bigint not null references public.game_cities(id) on delete cascade,period_key text not null,gdp_estimate bigint not null default 0,employment_rate numeric(7,4) not null default 0,average_wage bigint not null default 0,business_count integer not null default 0,household_consumption bigint not null default 0,created_at timestamptz not null default now(),unique(city_id,period_key));

alter table public.game_bank_accounts enable row level security; alter table public.game_bank_transfers enable row level security; alter table public.game_bank_loans enable row level security; alter table public.game_credit_history enable row level security; alter table public.game_personal_finance_snapshots enable row level security; alter table public.game_supply_chain enable row level security; alter table public.game_city_economy_snapshots enable row level security;
revoke all on public.game_bank_accounts,public.game_bank_transfers,public.game_bank_loans,public.game_credit_history,public.game_personal_finance_snapshots,public.game_supply_chain,public.game_city_economy_snapshots from anon,authenticated;
grant all on public.game_bank_accounts,public.game_bank_transfers,public.game_bank_loans,public.game_credit_history,public.game_personal_finance_snapshots,public.game_supply_chain,public.game_city_economy_snapshots to service_role;

-- Production functions: game_open_bank_account, game_bank_transfer, game_apply_bank_loan,
-- game_repay_bank_loan, game_buy_market_item, game_create_supply_order,
-- game_fulfill_supply_order, game_snapshot_personal_finance, game_run_city_economy_tick.
